-- 房间级回退参数对齐 1:1 兑换与 0.4~60 档位（整数列按 paralaba 口径存×10 单位；
-- BetScores 为透传字符串，仅后台桌台页原样展示，存显示口径）
UPDATE parabetroom SET BET_MIN=4,BET_MAX=600,BET_MIN_VICE=4,BET_MAX_VICE=600,
  BET_MIN_DRAW=4,BET_MAX_DRAW=600,EX_COIN=1,COIN_SC=1,
  BetScores='0.4,0.8,1.2,1.6,2,4,6,10,15,20,30,40,60',DefaultBetIndex=6
WHERE ID=54000 AND GAME_ID=54;
UPDATE pararoom SET BET_MIN=4,BET_MAX=600,EX_COIN=1,COIN_SC=1 WHERE ID=54000 AND GAME_ID=54;
COMMIT;

SELECT GameId,LineAgent,Revision,ConfigHash,UpdatedBy,UpdatedAt,LEFT(ConfigJson,80) j FROM mjhl_agent_config;
SELECT GameId,LineAgent,Revision,LEFT(SimulationSummary,60) s FROM mjhl_agent_config_history;
SELECT ID,BET_MIN,BET_MAX,EX_COIN,COIN_SC,BetScores,DefaultBetIndex FROM parabetroom WHERE GAME_ID=54;
SELECT ID,BET_MIN,BET_MAX,EX_COIN,COIN_SC FROM pararoom WHERE GAME_ID=54;
